begin;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000021','roast-a@example.invalid','{"username":"roast_alice"}'),
 ('00000000-0000-0000-0000-000000000022','roast-b@example.invalid','{"username":"roast_bob"}'),
 ('00000000-0000-0000-0000-000000000023','roast-c@example.invalid','{"username":"roast_carol"}');
insert into public.challenges(id,creator_id,title,starts_on,duration_days,aura_gain,aura_penalty,max_strikes)
 values('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000021','Roast game',current_date,30,100,25,3);
insert into public.challenge_participants(challenge_id,user_id,challenge_aura) values
 ('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000021',0),
 ('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022',0);
create table public.roast_test_ids(id uuid);
grant select,insert,delete on public.roast_test_ids to authenticated;
select ok(not has_function_privilege('anon','public.create_roast_duel(uuid,uuid)','execute'),'Anonymous users cannot create games');
select ok(not has_table_privilege('authenticated','public.roast_duels','insert'),'Clients cannot forge a result');
select ok(not has_schema_privilege('authenticated','aura_private','usage'),'Private choices cannot be queried by clients');
select ok(not has_function_privilege('authenticated','public.roast_duel_allowed(uuid,uuid,uuid)','execute'),'Internal authorization helper is private');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
set local role authenticated;
select throws_ok($$select public.create_duel('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022',10)$$,'P0001',null,'Legacy dice wagers are blocked server-side');
select throws_ok($$select public.attempt_aura_heist('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022',1)$$,'P0001',null,'Legacy random Aura Heist is blocked server-side');
select throws_ok($$select public.purchase_benefit((select id from public.benefits where challenge_id='10000000-0000-0000-0000-000000000021' and title='Aura Ward'))$$,'P0001',null,'Retired ward cannot charge an old client');
insert into public.roast_test_ids select public.create_roast_duel('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022');
select is((select status from public.roast_duels where id=(select id from public.roast_test_ids)),'pending','An empty Aura balance can invite for free');
select throws_ok($$select public.create_roast_duel('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022')$$,'P0001',null,'Duplicate open invitations are prevented');
select throws_ok($$select public.respond_roast_duel((select id from public.roast_test_ids),true)$$,'P0001',null,'Challenger cannot accept for the opponent');
select is(public.play_roast_duel((select id from public.roast_test_ids),1,'rock')->>'status','pending','No play before consent');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000023',true);
select is((select count(*) from public.roast_duels),0::bigint,'RLS hides games from outsiders');
select throws_ok($$select public.get_roast_duel((select id from public.roast_test_ids))$$,'P0001',null,'Outsider RPC cannot read a game');
select throws_ok($$select public.play_roast_duel((select id from public.roast_test_ids),1,'paper')$$,'P0001',null,'Outsider cannot play');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select throws_ok($$select public.respond_roast_duel((select id from public.roast_test_ids),null)$$,'P0001',null,'Null acceptance is rejected');
select is(public.respond_roast_duel((select id from public.roast_test_ids),true)->>'status','active','Opponent consents before the first round');
select throws_ok($$select public.play_roast_duel((select id from public.roast_test_ids),1,'lizard')$$,'P0001',null,'Invalid choices are rejected');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
select is(public.play_roast_duel((select id from public.roast_test_ids),1,'rock')->>'my_move','rock','First choice is locked');
select is(public.play_roast_duel((select id from public.roast_test_ids),1,'paper')->>'my_move','rock','A retry cannot change the locked choice');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select is(public.get_roast_duel((select id from public.roast_test_ids))->>'my_move',null,'Opponent cannot see the first choice');
select is(public.get_roast_duel((select id from public.roast_test_ids))->>'last_challenger_move',null,'Public game row reveals nothing early');
select is((public.play_roast_duel((select id from public.roast_test_ids),1,'scissors')->>'challenger_score')::int,1,'Rock beats scissors on server');
select is(public.play_roast_duel((select id from public.roast_test_ids),1,'paper')->>'my_move',null,'Stale request cannot submit into the next round');
reset role;
select is((select count(*) from aura_private.roast_duel_moves),0::bigint,'Revealed choices are removed from private storage');
set local role authenticated;
select public.play_roast_duel((select id from public.roast_test_ids),2,'paper');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
select is((public.play_roast_duel((select id from public.roast_test_ids),2,'paper')->>'challenger_score')::int,1,'A draw does not add a point');
select public.play_roast_duel((select id from public.roast_test_ids),3,'paper');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select is((public.play_roast_duel((select id from public.roast_test_ids),3,'rock')->>'challenger_score')::int,2,'Paper beats rock on server');
select public.play_roast_duel((select id from public.roast_test_ids),4,'paper');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
select is(public.play_roast_duel((select id from public.roast_test_ids),4,'scissors')->>'status','resolved','Scissors beats paper and third win ends the match');
select is(public.play_roast_duel((select id from public.roast_test_ids),4,'rock')->>'status','resolved','Finished-match retries are harmless');
reset role;
select is((select count(*) from public.settlement_events where challenge_id='10000000-0000-0000-0000-000000000021' and kind in('duel_won','duel_lost')),2::bigint,'Exactly one winner and loser event');
select is((select coalesce(sum(abs(amount)),0) from public.settlement_events where challenge_id='10000000-0000-0000-0000-000000000021'),0::bigint,'Events contain zero currency');
select is((select sum(challenge_aura) from public.challenge_participants where challenge_id='10000000-0000-0000-0000-000000000021'),0::bigint,'Aura stays unchanged throughout a complete match');
select is((select count(*) from public.player_xp_events where user_id in('00000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022')),0::bigint,'No XP can be farmed');
select ok((select roast_key between 0 and 39 from public.roast_duels where id=(select id from public.roast_test_ids)),'A stable roast index is stored');
select is((select game_roast_key::integer from public.settlement_events where user_id='00000000-0000-0000-0000-000000000022' and challenge_id='10000000-0000-0000-0000-000000000021' and kind='duel_lost'),(select roast_key from public.roast_duels where id=(select id from public.roast_test_ids)),'The loser also receives the exact roast in Activity');
delete from public.roast_test_ids;
set local role authenticated;
insert into public.roast_test_ids select public.create_roast_duel('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select public.respond_roast_duel((select id from public.roast_test_ids),true);
select public.play_roast_duel((select id from public.roast_test_ids),1,'rock');
reset role;
insert into public.user_blocks(blocker_id,blocked_id) values('00000000-0000-0000-0000-000000000022','00000000-0000-0000-0000-000000000021');
select is((select status from public.roast_duels where id=(select id from public.roast_test_ids)),'declined','Blocking closes an accepted match');
select is((select count(*) from aura_private.roast_duel_moves),0::bigint,'Blocking removes pending choices');
delete from public.user_blocks where blocker_id='00000000-0000-0000-0000-000000000022';
select is((select status from public.roast_duels where id=(select id from public.roast_test_ids)),'declined','Unblocking cannot revive a closed match');
delete from public.roast_test_ids;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000021',true);
insert into public.roast_test_ids select public.create_roast_duel('10000000-0000-0000-0000-000000000021','00000000-0000-0000-0000-000000000022');
reset role;
update public.roast_duels set expires_at=now()-interval '1 minute' where id=(select id from public.roast_test_ids);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000022',true);
select is(public.respond_roast_duel((select id from public.roast_test_ids),true)->>'status','expired','Expired invitation cannot be accepted');
reset role;
select * from finish();
rollback;
